import { useRouter } from 'expo-router';
import { ActivityIndicator, StyleSheet, View } from 'react-native';

import { ClearanceCard } from '@/components/clearance/clearance-card';
import { AppIllustration } from '@/components/illustrations/app-illustration';
import { DailyGoalCard } from '@/components/profile/daily-goal-card';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { MockBadge } from '@/components/ui/mock-badge';
import { Screen } from '@/components/ui/screen';
import { AppText } from '@/components/ui/text';
import { ThemeToggle } from '@/components/ui/theme-toggle';
import { PremiumWatchVisual } from '@/components/watch/premium-watch-visual';
import { radius, spacing } from '@/constants/theme';
import { useMockWatch } from '@/hooks/use-mock-watch';
import { useTheme } from '@/hooks/use-theme';
import { useTodayConditions } from '@/hooks/use-today-conditions';
import { FALLBACK_LOCATION_LABEL } from '@/services/location';

/** คำทักทายตามช่วงเวลาของวัน */
function greeting(now: number): string {
  const hour = new Date(now).getHours();
  if (hour < 12) return 'สวัสดีตอนเช้า';
  if (hour < 17) return 'สวัสดีตอนบ่าย';
  return 'สวัสดีตอนเย็น';
}

export default function HomeScreen() {
  const router = useRouter();
  const { colors } = useTheme();
  const mockWatch = useMockWatch('rest');
  const { status, clearance, conditions, location, error, evaluatedAt, reload } =
    useTodayConditions();

  return (
    <Screen title="พร้อมวิ่ง" headerRight={<ThemeToggle />}>
      <View style={[styles.hero, { backgroundColor: colors.brandSoft }]}>
        <View style={styles.greeting}>
          <AppText variant="small" color={colors.brandStrong}>
            {greeting(evaluatedAt || Date.now())}
          </AppText>
          <AppText variant="title" weight="bold">
            พร้อมวิ่งหรือยัง
          </AppText>
          {location?.isFallback ? (
            <AppText variant="caption" tone="faint">
              แสดงข้อมูลของ {FALLBACK_LOCATION_LABEL} เพราะยังไม่ได้รับสิทธิ์เข้าถึงตำแหน่ง
            </AppText>
          ) : null}
        </View>
        <AppIllustration name="fitnessStats" style={styles.heroIllustration} />
      </View>

      <View
        style={[
          styles.watchHero,
          { backgroundColor: colors.surface, borderColor: colors.border },
        ]}>
        <View style={styles.watchHeader}>
          <View style={styles.watchTitle}>
            <AppText variant="heading" weight="semibold">
              นาฬิกาคู่ใจ
            </AppText>
            <AppText variant="small" tone="muted">
              {mockWatch.device ? mockWatch.device.name : 'ลองเชื่อมต่ออุปกรณ์จำลอง'}
            </AppText>
          </View>
          <MockBadge label="ข้อมูลจำลอง" />
        </View>

        <PremiumWatchVisual />

        {mockWatch.device ? (
          <View style={styles.watchMetrics}>
            <View style={styles.watchMetric}>
              <AppText variant="caption" tone="faint">
                ชีพจรสดจำลอง
              </AppText>
              <AppText variant="heading" weight="bold" color={colors.clearRed}>
                {mockWatch.metrics.heartRateBpm} bpm
              </AppText>
            </View>
            <View style={styles.watchMetric}>
              <AppText variant="caption" tone="faint">
                ออกซิเจนในเลือด
              </AppText>
              <AppText variant="heading" weight="bold">
                {mockWatch.metrics.spo2Percent}%
              </AppText>
            </View>
            <View style={[styles.connectedPill, { backgroundColor: colors.clearGreenSoft }]}>
              <View style={[styles.connectedDot, { backgroundColor: colors.clearGreen }]} />
              <AppText variant="caption" weight="semibold" color={colors.clearGreen}>
                เชื่อมต่อ Demo
              </AppText>
            </View>
          </View>
        ) : (
          <AppText variant="small" tone="muted" align="center">
            เลือก Apple Watch, Garmin หรือ Prompt Band จำลอง แล้วดูข้อมูลสุขภาพตัวอย่างสด ๆ
          </AppText>
        )}

        <Button
          label={mockWatch.device ? 'ดูข้อมูลและเปลี่ยนนาฬิกา' : 'เลือกนาฬิกาจำลอง'}
          onPress={() => router.push('/mock-watch')}
          variant={mockWatch.device ? 'secondary' : 'primary'}
        />
      </View>

      {status === 'loading' ? (
        <Card>
          <View style={styles.loading}>
            <ActivityIndicator color={colors.brand} />
            <AppText variant="small" tone="muted">
              กำลังตรวจอากาศและฝุ่นรอบตัวคุณ
            </AppText>
          </View>
        </Card>
      ) : null}

      {status === 'error' ? (
        <Card>
          <AppText variant="heading" weight="semibold">
            ยังบอกไม่ได้ว่าวันนี้วิ่งได้ไหม
          </AppText>
          <AppText variant="body" tone="muted">
            {error ?? 'ดึงข้อมูลไม่สำเร็จ'}
          </AppText>
          <Button label="ลองอีกครั้ง" onPress={reload} variant="secondary" />
        </Card>
      ) : null}

      {status === 'ready' && clearance !== null && conditions !== null ? (
        <ClearanceCard
          clearance={clearance}
          conditions={conditions}
          now={evaluatedAt}
          onPress={() => router.push('/weather')}
        />
      ) : null}

      <DailyGoalCard />

      <Card>
        <AppText variant="heading" weight="semibold">
          วอร์มอัพ
        </AppText>
        <AppText variant="body" tone="muted">
          ชุดท่าที่เลือกมาให้สำหรับวันนี้โดยเฉพาะ ตามอากาศตอนนี้และปรับความยาวได้
        </AppText>
        <Button label="เริ่มวอร์มอัพ" onPress={() => router.push('/warmup')} variant="secondary" />
      </Card>
    </Screen>
  );
}

const styles = StyleSheet.create({
  hero: {
    minHeight: 142,
    borderRadius: radius.xl,
    padding: spacing.lg,
    flexDirection: 'row',
    alignItems: 'center',
    overflow: 'hidden',
  },
  greeting: { flex: 1, gap: spacing.xs, zIndex: 1 },
  heroIllustration: { width: 142, height: 112, marginRight: -spacing.md },
  watchHero: {
    borderRadius: radius.xl,
    borderWidth: StyleSheet.hairlineWidth,
    padding: spacing.lg,
    gap: spacing.md,
    overflow: 'hidden',
  },
  watchHeader: {
    flexDirection: 'row',
    alignItems: 'flex-start',
    justifyContent: 'space-between',
    gap: spacing.md,
  },
  watchTitle: { flex: 1, gap: 2 },
  watchMetrics: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    alignItems: 'center',
    gap: spacing.md,
  },
  watchMetric: { flex: 1, minWidth: 120 },
  connectedPill: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: spacing.xs,
    borderRadius: radius.pill,
    paddingHorizontal: spacing.sm,
    paddingVertical: spacing.xs,
  },
  connectedDot: { width: 7, height: 7, borderRadius: 4 },
  loading: { alignItems: 'center', gap: spacing.md, paddingVertical: spacing.lg },
});

